{"code": "(function() {
  // Search for 6-character alphanumeric patterns in the page
  const bodyText = document.body.innerText;
  const codePattern = /\b[a-zA-Z0-9]{6}\b/g;
  const matches = bodyText.match(codePattern);

  // Also look for elements with specific classes or IDs that might contain codes
  const codeElements = document.querySelectorAll('[class*="code"], [id*="code"], [data-code]');
  const elementCodes = [];
  codeElements.forEach(el => {
    elementCodes.push({
      tag: el.tagName,
      text: el.textContent?.substring(0, 50),
      class: el.className,
      id: el.id
    });
  });

  return {
    sixCharMatches: matches ? [...new Set(matches)] : 'No 6-char patterns found',
    codeElements: elementCodes
  };
})()"}

{"code": "(function() {
  // Look for elements with aria-label, data-*, or other attributes that might contain the code
  const allElements = document.querySelectorAll('*');
  const results = [];

  allElements.forEach(el => {
    // Check aria-label
    if (el.getAttribute('aria-label')) {
      results.push({
        tag: el.tagName,
        ariaLabel: el.getAttribute('aria-label'),
        id: el.id,
        class: el.className?.substring(0, 50)
      });
    }

    // Check data attributes
    for (let attr of el.attributes) {
      if (attr.name.startsWith('data-') && attr.value) {
        // Look for 6-character patterns in data attributes
        if (/\b[a-zA-Z0-9]{6}\b/.test(attr.value)) {
          results.push({
            tag: el.tagName,
            attribute: attr.name,
            value: attr.value,
            id: el.id
          });
        }
      }
    }
  });

  // Also look for meta tags
  const metaTags = document.querySelectorAll('meta');
  metaTags.forEach(meta => {
    if (meta.name || meta.content) {
      results.push({
        tag: 'meta',
        name: meta.name,
        content: meta.content
      });
    }
  });

  return results;
})()"}

